    // Launch kernel to compute hinge loss per element
    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    hinge_loss_kernel<<<grid_size, block_size, 0, at::cuda::getCurrentCUDAStream()>>>(
        predictions.data_ptr<half>(),
        targets.data_ptr<half>(),
        output.data_ptr<half>(),
        total_elements
