    const int reduce_block_size = 256;
    const int reduce_grid_size = (total_elements + reduce_block_size - 1) / reduce_block_size;

    reduce_mean_kernel<<<reduce_grid_size, reduce_block_size, reduce_block_size * sizeof(half), at::cuda::getCurrentCUDAStream()>>>(
        output.data_ptr<half>(),
        sum_tensor.data_ptr<half>(),
        total_elements
